const assets={"/index.html":"﻿<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"Order eggs from Olaoyin Store. Choose your quantity and send your order on WhatsApp. Prices confirmed after ordering.\"><title>Olaoyin Store | Fresh eggs</title><style>\n*{box-sizing:border-box}body{margin:0;background:#faf8f0;color:#243d2e;font-family:system-ui,sans-serif}header,main,footer{max-width:1080px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dedfd3}.brand{font-size:23px;font-weight:800}.badge{font-size:12px;background:#e6eddb;padding:9px 14px;border-radius:30px}.hero{display:grid;grid-template-columns:1.4fr 1fr;gap:30px;align-items:center;padding:45px 0 35px}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:bold;color:#7b824e}h1{font-family:Georgia,serif;font-size:clamp(40px,6vw,65px);letter-spacing:-2px;line-height:1.05;margin:17px 0}p{color:#637060;line-height:1.65}.art{background:#e7ecd8;border-radius:120px 120px 22px 22px;height:230px;display:flex;align-items:center;justify-content:center;gap:8px}.egg{background:linear-gradient(120deg,#fff9e9,#d1ae78);width:70px;height:95px;border-radius:50% 50% 45% 45%;box-shadow:7px 14px 15px #63755233;transform:rotate(-14deg)}.egg:nth-child(2){transform:translateY(-24px) rotate(12deg)}.layout{display:grid;grid-template-columns:1fr 380px;gap:30px}h2{font-size:22px;margin:0 0 18px}.product{display:flex;align-items:center;gap:15px;padding:20px;background:white;border:1px solid #e0e3d7;border-radius:17px;margin-bottom:12px}.icon{font-size:30px;padding:10px;background:#f4efe1;border-radius:12px}.info{flex:1}.info h3{font-size:17px;margin:0 0 5px}.info p{font-size:13px;margin:0}.counter{display:flex;gap:14px;align-items:center}button{font:inherit;cursor:pointer;border:0}.counter button{width:33px;height:33px;border-radius:50%;background:#eaf0e3;color:#254d33;font-weight:bold}button:disabled{opacity:.45;cursor:not-allowed}.panel{background:white;border:1px solid #e0e3d7;padding:24px;border-radius:22px}.summary{font-size:14px;line-height:1.8;padding-bottom:15px;border-bottom:1px solid #e0e3d7}label{display:block;margin:16px 0 6px;font-weight:600;font-size:13px}input,select,textarea{width:100%;font:inherit;padding:12px;color:#243d2e;background:white;border:1px solid #d4dccd;border-radius:9px}textarea{resize:vertical}.submit{background:#285a3d;color:white;width:100%;padding:15px;border-radius:10px;font-weight:700;margin-top:20px}.note{font-size:12px}.pricing{padding:16px;background:#ebefdf;border-radius:12px;font-size:14px;color:#475a39}a{color:#285a3d}footer{font-size:12px;color:#637060}button:focus-visible,a:focus-visible{outline:3px solid #b98c30;outline-offset:3px}@media(max-width:740px){header,main,footer{padding:20px}.badge{font-size:10px;padding:8px}.brand{font-size:19px}.hero{grid-template-columns:1fr;padding:30px 0}.art{display:none}.layout{grid-template-columns:1fr;gap:20px}.product{padding:15px;gap:10px}.icon{padding:7px;font-size:25px}}\n</style></head><body><header><div class=\"brand\">🥚 Olaoyin Store</div><span class=\"badge\">Order fresh eggs</span></header><main><section class=\"hero\"><div><span class=\"eyebrow\">YOUR EVERYDAY EGG SHOP</span><h1>Good mornings<br>start with eggs.</h1><p>Choose your eggs and place your order.<br>We’ll confirm today’s price with you on WhatsApp.</p></div><div class=\"art\" aria-hidden=\"true\"><div class=\"egg\"></div><div class=\"egg\"></div><div class=\"egg\"></div></div></section><div class=\"layout\"><section><h2>Choose your quantity</h2><div id=\"products\"></div><p class=\"pricing\">No fixed prices. We’ll confirm the current price and availability before you commit to buying.</p><p class=\"note\">A full crate contains 30 eggs. Any delivery arrangement and charge will be confirmed on WhatsApp.</p></section><form class=\"panel\" id=\"order\"><h2>Your order</h2><div class=\"summary\" id=\"summary\" aria-live=\"polite\">Choose a quantity to get started.</div><label for=\"name\">Your name</label><input id=\"name\" autocomplete=\"name\" required maxlength=\"100\"><label for=\"phone\">Your phone number</label><input id=\"phone\" type=\"tel\" autocomplete=\"tel\" required maxlength=\"30\"><label for=\"email\">Email for payment receipt</label><input id=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"254\"><label for=\"method\">How would you like your eggs?</label><select id=\"method\"><option value=\"pickup\">Request pickup</option><option value=\"delivery\">Request delivery</option></select><div id=\"addressWrap\" hidden><label for=\"address\">Delivery address</label><textarea id=\"address\" autocomplete=\"street-address\" maxlength=\"500\"></textarea></div><label for=\"notes\">Additional details (optional)</label><textarea id=\"notes\" placeholder=\"Preferred date or special instructions\" maxlength=\"500\"></textarea><button class=\"submit\" id=\"checkout\" disabled>Place order</button><p class=\"note\" id=\"status\" role=\"status\">Your order will be saved. Keep your private order link to track progress and pay once we confirm the total.</p></form></div></main><footer>Olaoyin Store · <a href=\"https://wa.me/2348028091950\">Chat with us</a> · <a href=\"https://wa.me/2347066052334\">Alternative WhatsApp</a> · <a href=\"/admin.html\">Manage orders</a></footer><script src=\"app.js\"></script><script src=\"checkout.js\"></script></body></html>\r\n","/app.js":"﻿'use strict';\nconst products=[{id:'egg',name:'Single eggs',eggs:1},{id:'half',name:'Half crate',eggs:15},{id:'crate',name:'Full crate',eggs:30}];\nconst quantities=Object.fromEntries(products.map(p=>[p.id,0]));\nconst el=id=>document.getElementById(id);\nconst chosen=()=>products.filter(p=>quantities[p.id]>0);\nfunction render(){el('summary').replaceChildren();const items=chosen();if(!items.length){el('summary').textContent='Choose a quantity to get started.';}else{for(const p of items){const row=document.createElement('div');row.textContent=quantities[p.id]+' × '+p.name;el('summary').append(row);}const note=document.createElement('strong');note.textContent='Price: confirmed on WhatsApp';el('summary').append(note);}el('checkout').disabled=!items.length;}\nfor(const p of products){const card=document.createElement('div');card.className='product';const icon=document.createElement('span');icon.className='icon';icon.textContent='🥚';icon.setAttribute('aria-hidden','true');const info=document.createElement('div');info.className='info';const title=document.createElement('h3');title.textContent=p.name;const detail=document.createElement('p');detail.textContent=p.eggs===1?'Choose the number of eggs':p.eggs+' eggs per '+(p.id==='half'?'half crate':'crate');info.append(title,detail);const controls=document.createElement('div');controls.className='counter';const minus=document.createElement('button');minus.type='button';minus.textContent='−';minus.setAttribute('aria-label','Remove '+p.name);const count=document.createElement('span');count.textContent='0';count.setAttribute('aria-live','polite');const plus=document.createElement('button');plus.type='button';plus.textContent='+';plus.setAttribute('aria-label','Add '+p.name);function change(delta){quantities[p.id]=Math.max(0,Math.min(999,quantities[p.id]+delta));count.textContent=quantities[p.id];minus.disabled=quantities[p.id]===0;plus.disabled=quantities[p.id]===999;render();}minus.onclick=()=>change(-1);plus.onclick=()=>change(1);minus.disabled=true;controls.append(minus,count,plus);card.append(icon,info,controls);el('products').append(card);}\nel('method').onchange=()=>{const delivery=el('method').value==='delivery';el('addressWrap').hidden=!delivery;el('address').required=delivery;};\nel('order').onsubmit=event=>{event.preventDefault();if(!chosen().length||!el('order').reportValidity())return;for(const id of ['name','phone',...(el('method').value==='delivery'?['address']:[])]){if(!el(id).value.trim()){el(id).setCustomValidity('Please complete this field.');el(id).reportValidity();el(id).oninput=()=>el(id).setCustomValidity('');return;}}const lines=['Hello Olaoyin Store, I would like to order:',...chosen().map(p=>quantities[p.id]+' × '+p.name),'Total eggs: '+chosen().reduce((n,p)=>n+p.eggs*quantities[p.id],0),'','Name: '+el('name').value.trim(),'Phone: '+el('phone').value.trim(),'Request: '+el('method').value];if(el('method').value==='delivery')lines.push('Delivery address: '+el('address').value.trim());if(el('notes').value.trim())lines.push('Notes: '+el('notes').value.trim());lines.push('','Please confirm the current price, availability, and any delivery charge.');const seller=el('seller').value;if(!['2348028091950','2347066052334'].includes(seller))return;window.location.assign('https://wa.me/'+seller+'?text='+encodeURIComponent(lines.join('\\n')));};render();\r\n","/checkout.js":"// Save the order before taking the customer to its private status page.\nel('order').onsubmit=async event=>{\n event.preventDefault();if(!chosen().length||!el('order').reportValidity())return;\n const button=el('checkout');button.disabled=true;\n try{const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:el('name').value,phone:el('phone').value,email:el('email').value,method:el('method').value,address:el('address').value,notes:el('notes').value,items:chosen().map(p=>({id:p.id,quantity:quantities[p.id]}))})});const result=await response.json();if(!response.ok)throw Error(result.error);location.assign('/order.html#'+result.id+':'+result.token);}catch(error){el('status').textContent=error.message||'Could not save your order. Please try again.';}finally{button.disabled=false;}\n};\n","/admin.html":"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manage orders · Olaoyin Store</title><style>body{font:16px system-ui;background:#faf8f0;color:#243d2e;max-width:1000px;margin:30px auto;padding:20px}article{background:white;border:1px solid #dde3d7;padding:20px;border-radius:16px;margin:16px 0}p{overflow-wrap:anywhere}input,select,button{font:inherit;padding:10px;margin:5px;border:1px solid #ccd6c8;border-radius:8px}button{background:#285a3d;color:white}label{display:inline-block}a{color:#285a3d}</style><a href=\"/\">← Store</a><h1>Manage orders</h1><a href=\"/signin-with-chatgpt?returnTo=%2Fadmin.html\" target=\"_top\">Sign in with ChatGPT</a><button id=\"refresh\">Refresh</button><label>Filter <select id=\"filter\"><option value=\"\">All orders</option><option>new</option><option>confirmed</option><option>ready</option><option>completed</option><option>cancelled</option></select></label><p id=\"message\" role=\"status\"></p><main id=\"orders\"></main><script src=\"admin.js\"></script></html>\n","/admin.js":"const $=id=>document.getElementById(id);let orders=[];\nasync function load(){try{const r=await fetch('/api/admin/orders');const b=await r.json();if(!r.ok)throw Error(b.error);orders=b;$('message').textContent=orders.length+' orders (latest 500).';render();}catch(e){$('message').textContent=e.message;}}\nfunction render(){$('orders').replaceChildren();for(const o of orders.filter(o=>!$('filter').value||o.status===$('filter').value)){\n const card=document.createElement('article');for(const text of [o.name+' · '+o.phone,o.email,new Date(o.created_at).toLocaleString(),JSON.parse(o.items).map(p=>p.quantity+' × '+({egg:'Single eggs',half:'Half crate',crate:'Full crate'}[p.id])).join(', '),o.method+(o.address?' · '+o.address:''),o.notes,'Payment: '+o.payment_status]){const p=document.createElement('p');p.textContent=text;card.append(p);}\n const status=document.createElement('select');status.setAttribute('aria-label','Order status');for(const value of ['new','confirmed','ready','completed','cancelled']){const option=document.createElement('option');option.value=value;option.textContent=value;status.append(option);}status.value=o.status;\n const label=document.createElement('label');label.textContent='Total including delivery (₦)';const amount=document.createElement('input');amount.type='number';amount.min='50';amount.max='1000000';amount.step='0.01';amount.value=o.amount===null?'':o.amount/100;amount.disabled=Boolean(o.payment_reference)||o.payment_status==='paid';label.append(amount);\n const save=document.createElement('button');save.textContent='Save order';save.onclick=async()=>{save.disabled=true;try{if(amount.value&&!amount.checkValidity())throw Error('Enter a valid total.');const r=await fetch('/api/admin/orders',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:o.id,status:status.value,amount:amount.value?Math.round(Number(amount.value)*100):null})});const b=await r.json();if(!r.ok)throw Error(b.error);await load();}catch(e){$('message').textContent=e.message;}finally{save.disabled=false;}};\n const link=document.createElement('a');link.textContent='Open private order link';link.href='/order.html#'+o.id+':'+o.token;link.target='_blank';link.rel='noopener';card.append(status,label,save,document.createElement('br'),link);$('orders').append(card);\n}}\n$('filter').onchange=render;$('refresh').onclick=load;load();\n","/order.html":"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Your order · Olaoyin Store</title><style>body{font:16px system-ui;background:#faf8f0;color:#243d2e;max-width:650px;margin:40px auto;padding:20px}button,a{margin:8px 8px 8px 0}button{padding:12px;border:0;border-radius:8px;background:#285a3d;color:white}section{background:white;padding:24px;border-radius:16px}p{line-height:1.6}</style><a href=\"/\">← Olaoyin Store</a><h1>Your order</h1><section><div id=\"details\">Loading…</div><button id=\"refresh\">Refresh status</button><button id=\"pay\" hidden>Pay online</button><button id=\"verify\" hidden>Check payment</button><p id=\"message\" role=\"status\"></p><a id=\"whatsapp\" hidden target=\"_blank\" rel=\"noopener\">Discuss this order on WhatsApp</a></section><p>Keep this private order link to check progress and pay after the store confirms your total. Anyone with the link can view this order.</p><script src=\"order.js\"></script></html>\n","/order.js":"const $=id=>document.getElementById(id);\nconst [id,token]=location.hash.slice(1).split(':');\nasync function api(action='',method='GET'){const r=await fetch('/api/orders/'+encodeURIComponent(id)+(action?'/'+action:''),{method,headers:{'X-Order-Token':token||''}});const b=await r.json();if(!r.ok)throw Error(b.error);return b;}\nasync function load(){try{const o=await api();$('details').replaceChildren();for(const text of ['Order: '+o.id,'Customer: '+o.name,'Items: '+JSON.parse(o.items).map(p=>p.quantity+' × '+({egg:'Single eggs',half:'Half crate',crate:'Full crate'}[p.id])).join(', '),'Status: '+o.status,'Total: '+(o.amount===null?'Awaiting seller confirmation':new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN'}).format(o.amount/100)),'Payment: '+o.payment_status]){const p=document.createElement('p');p.textContent=text;$('details').append(p);} $('pay').hidden=!(o.status==='confirmed'&&o.amount&&o.payment_status!=='paid'&&o.payments_enabled);$('verify').hidden=!o.payment_reference||o.payment_status==='paid';$('whatsapp').hidden=false;$('whatsapp').href='https://wa.me/2348028091950?text='+encodeURIComponent('Hello, please confirm my egg order '+o.id+'. My private order link: '+location.origin+'/order.html#'+id+':'+token);}catch(e){$('message').textContent=e.message;}}\n$('refresh').onclick=load;\n$('pay').onclick=async()=>{$('pay').disabled=true;try{const b=await api('pay','POST');if(b.verify){$('message').textContent='Payment found. Tap Check payment to confirm.';}else location.assign(b.url);}catch(e){$('message').textContent=e.message;}finally{$('pay').disabled=false;await load();}};\n$('verify').onclick=async()=>{try{const b=await api('verify','POST');$('message').textContent=b.paid?'Payment confirmed. Thank you!':'Payment has not been confirmed yet. Please check again later.';await load();}catch(e){$('message').textContent=e.message;}};\nload();\n"};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const fail=(message,status=400)=>{throw Object.assign(new Error(message),{status});};
export function validateOrder(b){
 const out={};
 for(const [key,max] of Object.entries({name:100,phone:30,email:254,address:500,notes:500})){
  if(typeof b[key]!=='string'||b[key].length>max)fail('Invalid '+key);
  out[key]=b[key].trim();
 }
 if(!out.name||!/^\+?[\d ()-]{7,30}$/.test(out.phone)||!/^\S+@\S+\.\S+$/.test(out.email))fail('Enter a valid name, phone number and email.');
 if(!['pickup','delivery'].includes(b.method)||b.method==='delivery'&&!out.address)fail('Provide delivery details.');
 out.method=b.method;
 if(!Array.isArray(b.items)||!b.items.length||b.items.length>3)fail('Choose your eggs.');
 const ids=new Set();
 out.items=b.items.map(p=>{if(!['egg','half','crate'].includes(p.id)||ids.has(p.id)||!Number.isInteger(p.quantity)||p.quantity<1||p.quantity>999)fail('Invalid quantity');ids.add(p.id);return {id:p.id,quantity:p.quantity};});
 return out;
}
const admin=(r,e)=>Boolean(e.ADMIN_EMAIL&&r.headers.get('oai-authenticated-user-email')?.toLowerCase()===e.ADMIN_EMAIL.toLowerCase());
async function body(r){if(Number(r.headers.get('content-length'))>8192)fail('Request too large',413);const raw=await r.text();if(raw.length>8192)fail('Request too large',413);try{return JSON.parse(raw);}catch{fail('Invalid JSON');}}
async function paystack(env,path,data){
 if(!env.PAYSTACK_SECRET_KEY)fail('Online payment is not configured yet. Please contact the store.',503);
 const res=await fetch('https://api.paystack.co/transaction/'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+env.PAYSTACK_SECRET_KEY,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});
 const result=await res.json();if(!res.ok||!result.status)fail('Payment provider is unavailable. Please try again.',502);return result.data;
}
export async function handle(request,env){
 const url=new URL(request.url),path=url.pathname;
 try{
  if(!['GET','HEAD'].includes(request.method)&&request.headers.get('origin')!==url.origin)fail('Invalid origin',403);
  if(path.startsWith('/api/')){
   if(!env.DB)fail('Order storage is not configured.',503);
   if(path==='/api/orders'&&request.method==='POST'){
    const b=validateOrder(await body(request));const id=crypto.randomUUID(),token=crypto.randomUUID()+crypto.randomUUID();
    await env.DB.prepare('INSERT INTO orders(id,token,created_at,name,phone,email,method,address,notes,items) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(id,token,new Date().toISOString(),b.name,b.phone,b.email,b.method,b.address,b.notes,JSON.stringify(b.items)).run();
    return json({id,token},201);
   }
   if(path.startsWith('/api/admin')){
    if(!admin(request,env))fail('Sign in with the store administrator account.',403);
    if(path==='/api/admin/orders'&&request.method==='GET')return json((await env.DB.prepare('SELECT * FROM orders ORDER BY created_at DESC LIMIT 500').all()).results);
    if(path==='/api/admin/orders'&&request.method==='PATCH'){
     const b=await body(request);if(!['new','confirmed','ready','completed','cancelled'].includes(b.status))fail('Invalid status');
     if(b.amount!==null&&(!Number.isSafeInteger(b.amount)||b.amount<5000||b.amount>100000000))fail('Enter a total between ₦50 and ₦1,000,000.');
     const result=await env.DB.prepare("UPDATE orders SET status=?,amount=? WHERE id=? AND payment_status='unpaid' AND payment_reference IS NULL").bind(b.status,b.amount,b.id).run();
     if(!result.meta.changes){const existing=await env.DB.prepare('SELECT amount FROM orders WHERE id=?').bind(b.id).first();if(!existing)fail('Order not found',404);if(existing.amount!==b.amount)fail('A payment has started; its total cannot be changed.',409);await env.DB.prepare('UPDATE orders SET status=? WHERE id=?').bind(b.status,b.id).run();}
     return json({ok:true});
    }
   }
   const match=path.match(/^\/api\/orders\/([a-f0-9-]+)(?:\/(pay|verify))?$/);
   if(match){
    const token=request.headers.get('X-Order-Token');if(!token)fail('Order access required',403);
    const order=await env.DB.prepare('SELECT * FROM orders WHERE id=? AND token=?').bind(match[1],token).first();if(!order)fail('Order not found',404);
    if(!match[2]&&request.method==='GET'){delete order.token;return json({...order,payments_enabled:Boolean(env.PAYSTACK_SECRET_KEY)});}
    if(match[2]==='pay'&&request.method==='POST'){
     if(order.status!=='confirmed'||!order.amount||order.payment_status==='paid')fail('This order is not awaiting payment.',409);
     if(!env.PAYSTACK_SECRET_KEY)fail('Online payment is not configured yet.',503);
     if(order.checkout_url)return json({url:order.checkout_url});
     const reference='egg-'+crypto.randomUUID();
     await env.DB.prepare('UPDATE orders SET payment_reference=COALESCE(payment_reference,?) WHERE id=?').bind(reference,order.id).run();
     const current=await env.DB.prepare('SELECT payment_reference FROM orders WHERE id=?').bind(order.id).first();
     // Reuse an existing checkout after a retry, without creating a second charge.
     if(current.payment_reference!==reference){const previous=await paystack(env,'verify/'+encodeURIComponent(current.payment_reference));if(previous.status==='success')return json({verify:true});fail('A payment attempt already exists. Use Check payment or contact the store before retrying.',409);}
     const result=await paystack(env,'initialize',{email:order.email,amount:order.amount,currency:'NGN',reference,callback_url:url.origin+'/order.html#'+order.id+':'+token});
     await env.DB.prepare('UPDATE orders SET checkout_url=? WHERE id=? AND payment_reference=?').bind(result.authorization_url,order.id,reference).run();
     return json({url:result.authorization_url});
    }
    if(match[2]==='verify'&&request.method==='POST'){
     if(!order.payment_reference)fail('No payment has started.');
     const payment=await paystack(env,'verify/'+encodeURIComponent(order.payment_reference));
     if(payment.status==='success'&&payment.reference===order.payment_reference&&payment.amount===order.amount&&payment.currency==='NGN'){
      await env.DB.prepare("UPDATE orders SET payment_status='paid' WHERE id=?").bind(order.id).run();return json({paid:true});
     }return json({paid:false});
    }
   }
   fail('Not found',404);
  }
  const file=path==='/'?'/index.html':path;
  if(!Object.hasOwn(assets,file))return new Response('Not found',{status:404});
  return new Response(request.method==='HEAD'?null:assets[file],{headers:{'Content-Type':file.endsWith('.js')?'text/javascript; charset=utf-8':'text/html; charset=utf-8','Cache-Control':'no-store','Referrer-Policy':'no-referrer','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; base-uri 'none'; form-action 'self'; frame-ancestors 'self'"}});
 }catch(error){if(!error.status)console.error('Order API failed',error.message);return json({error:error.status?error.message:'Something went wrong. Please try again.'},error.status||500);}
}
export default {fetch:handle};
